examples.code:
#include <atomic>
#include <iostream>

int main() {
    alignas(std::atomic_ref<int>::required_alignment) int storage{4};
    std::atomic_ref<int> count{storage};
    count.store(8);
    std::cout << count.load() << "\n";
    count = 10;
    int previous = count.exchange(12);
    std::cout << previous << " -> " << static_cast<int>(count) << "\n";
}
